import numpy as np

rng = np.random.default_rng(0)
area = rng.uniform(1, 10, size=50)
price = 3 * area + 2 + rng.normal(0, 1, size=50)
X_demo = np.column_stack([area, np.ones(50)])

def fit_normal(X, y):
    return np.linalg.solve(X.T @ X, X.T @ y)

def project(X, y):
    return X @ fit_normal(X, y)
